import React, { useEffect, useState } from "react";
import "./style.css";
import { Link, useNavigate } from "react-router-dom";
import CategoriesService from "../../../services/CategoriesService";
import { useSelector } from "react-redux";
import "swiper/css";
import arrowIcon from "../../../assets/arrow-right.svg";
import { useTranslation } from "react-i18next";
import { Card } from "react-bootstrap";

const Categories = () => {
	const [data, setData] = useState([]);
	const { t } = useTranslation();
	const [viewAll, setViewAll] = useState(false);
	const lang = useSelector((state) => state?.lang?.lang);
	const categoriesService = new CategoriesService();
	const navigate = useNavigate();

	useEffect(() => {
		let params = {
			offset: 0,
			limit: 8,
		};
		categoriesService
			?.getList(params)
			.then((res) => {
				if (res?.status === 200) {
					let info = res?.data?.data?.data?.map((cat) => {
						return {
							...cat,
						};
					});
					setData(info);
					if (info?.length) setViewAll(true);
				}
			})
			.catch(() => {});
	}, []);

	return (
		<div className="categories-home">
			<h1 className="section-title mb-5 mt-5">{t("categories")}</h1>
			<div className="section-categories">
				<div className="row">
					{data?.slice(0, 7)?.map((category) => {
						return (
							<div className="col-md-3 col-12 mb-3">
								<Card
									className="p-2 border-0"
									style={{ background: "#dedede50" }}>
									<Link
										to={`/category/${category.id}`}
										key={category?.id}
										style={{ textDecoration: "none" }}
										className="category-card">
										<img
											src={category?.image}
											alt="category"
											className="main-img w-100"
										/>
									</Link>
								</Card>
							</div>
						);
					})}
					{viewAll && (
						<div
							className="col-md-3 col-12 mb-3"
							onClick={() => navigate("/categories")}>
							<div className="d-flex flex-column align-items-center custom-category h-100 justify-content-center">
								<h1 className="view-all text-white mb-2">{t("View All")}</h1>
								<img src={arrowIcon} alt="arrow-icon" className="arrowIcon" />
							</div>
						</div>
					)}
				</div>
			</div>
		</div>
	);
};

export default Categories;
