import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { useSelector } from "react-redux";
import ProductsService from "../../../services/ProductsService";
import Loader from "../../../common/Loader";
import { Swiper, SwiperSlide } from "swiper/react";
import { Pagination } from "swiper/modules";

const BestProducts = () => {
	const [tabs, setTabs] = useState([]);
	const navigate = useNavigate();
	const [loader, setLoader] = useState(false);
	const { t } = useTranslation();

	const lang = useSelector((state) => state?.lang?.lang);
	const productsService = new ProductsService();

	useEffect(() => {
		let params = {
			offset: 0,
			limit: 8,
		};
		let allFun = [productsService?.getList({ ...params, bestSeller: true })];
		setLoader(true);
		Promise.all(allFun).then((res) => {
			if (res[0]?.status === 200) {
				setTabs([{ label: "Best seller", data: res[0]?.data?.data?.data }]);
			}
			setLoader(false);
		});
	}, []);

	if (loader) {
		return;
	}
	return (
		<div className="products-section">
			<div className="container">
				{tabs?.map((tab, index) => {
					return (
						<div key={index} className="mb-5">
							<h1 className="section-title">{t(tab?.label)}</h1>
							<div>
								{!!tab?.data?.length ? (
									<Swiper
										slidesPerView={1.5}
										spaceBetween={20}
										pagination={{
											clickable: true,
										}}
										modules={[Pagination]}
										breakpoints={{
											640: {
												slidesPerView: 2,
												spaceBetween: 20,
											},
											768: {
												slidesPerView: 3,
												spaceBetween: 25,
											},
											1024: {
												slidesPerView: 4,
												spaceBetween: 30,
											},
										}}
										className="mySwiper">
										{tab?.data?.map((item, index) => {
											return (
												<SwiperSlide
													key={index}
													onClick={() =>
														navigate(`/products/product/${item?.id}`)
													}
													className="product-card">
													<img
														src={
															!!item?.product_images?.length
																? item?.product_images[0]?.url
																: ""
														}
														alt="product"
														className="w-100"
													/>
													<p className="title">
														{lang === "en" ? item?.name_en : item?.name_ar}
													</p>
													<p className="price">
														{item?.price?.toFixed(3)} {t("KWD")}
													</p>
												</SwiperSlide>
											);
										})}
									</Swiper>
								) : (
									<h3 className="pb-5">{t(`There's no Product`)}</h3>
								)}
							</div>
						</div>
					);
				})}
			</div>
		</div>
	);
};

export default BestProducts;
